            //
            aOrbiterK = ((aWandererE + RotL64(aScatter, 21U)) + RotL64(aCarry, 47U)) + 0x92CAAC9483E46630ULL;
            aOrbiterF = (aWandererA + RotL64(aIngress, 41U)) + 0x16BDE204E1EB606CULL;
            aOrbiterB = ((aWandererH + RotL64(aCross, 12U)) + RotL64(aCarry, 19U)) + 0xB9397C694C475423ULL;
            aOrbiterI = ((aWandererG + RotL64(aPrevious, 27U)) + 0x6A04530192BC8972ULL) + aPhaseDOrbiterAssignSaltA[(((31U - aIndex) + 8U)) & S_SALT1];
            aOrbiterC = (aWandererI + RotL64(aScatter, 5U)) + 0x230AE8427734A14EULL;
            aOrbiterE = (aWandererK + RotL64(aIngress, 47U)) + 0x1248BE8730E6C959ULL;
            aOrbiterJ = (((aWandererF + RotL64(aPrevious, 35U)) + RotL64(aCarry, 35U)) + 0xBCF0B8B250288725ULL) + aPhaseDOrbiterAssignSaltC[((aIndex + 18U)) & S_SALT1];
            //
            aOrbiterK = ((aOrbiterK + aOrbiterF) + 0xA1520B6EBE85ACE4ULL) + aPhaseDOrbiterUpdateSaltE[(((31U - aIndex) + 11U)) & S_SALT1];
