            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x8C763B0296CD4D47ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterF) ^ 0xFC86849EE2819131ULL;
            aOrbiterI = RotL64((aOrbiterI * 0x878C6EA16206798DULL), 11U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterB) + 0x9217ADF166A1CD28ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterE) ^ 0x303581953CD9A3C2ULL;
