            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterC) + 0x392A45597870D5C7ULL) + aPhaseDOrbiterUpdateSaltD[(((31U - aIndex) + 19U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0x3EBFA5D51B90FB13ULL;
